import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";

/**
 * Where uploaded bytes live. The database row (e.g. `service_request_attachments`) is the
 * authorization record; nothing here is ever served without first loading that row inside the
 * tenant boundary. Keys are generated by the API, never taken from user input.
 */
export interface ObjectStorage {
  readonly name: string;
  put(key: string, bytes: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
}

const KEY_PATTERN = /^[a-z0-9-]+(?:\/[a-z0-9-]+)*\.[a-z0-9]+$/;

function assertSafeKey(key: string): void {
  if (!KEY_PATTERN.test(key))
    throw new Error(`Refusing unsafe storage key: ${JSON.stringify(key)}`);
}

/**
 * Local-disk storage for development and single-node setups. Production should use an
 * S3-compatible private bucket implementing the same interface (see docs/DEPLOYMENT.md).
 */
export class LocalDiskStorage implements ObjectStorage {
  readonly name = "local-disk";
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  private pathFor(key: string): string {
    assertSafeKey(key);
    const full = resolve(this.root, key);
    if (!full.startsWith(this.root + sep)) throw new Error("Storage key escapes the storage root");
    return full;
  }

  async put(key: string, bytes: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, bytes, { flag: "wx", mode: 0o600 });
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathFor(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }
}

/** In-memory storage used by automated tests. */
export class MemoryStorage implements ObjectStorage {
  readonly name = "memory";
  readonly objects = new Map<string, { bytes: Buffer; contentType: string }>();

  async put(key: string, bytes: Buffer, contentType: string): Promise<void> {
    assertSafeKey(key);
    if (this.objects.has(key)) throw new Error("Object already exists");
    this.objects.set(key, { bytes, contentType });
  }

  async get(key: string): Promise<Buffer | null> {
    return this.objects.get(key)?.bytes ?? null;
  }
}
